import{_ as e}from"./chunks/settings-robot.pc.en.DW3gmNOs.js";import{_ as o}from"./chunks/log-bb-player.pc.en.i6OweW45.js";import{_ as a,o as s,c as n,a5 as r}from"./chunks/framework.D47SInms.js";const b=JSON.parse('{"title":"Technical Support","description":"","frontmatter":{"layout":"doc","outline":"deep","title":"Technical Support"},"headers":[],"relativePath":"manual/support/index.md","filePath":"manual/support/index.md","lastUpdated":1791600043000}'),i={name:"manual/support/index.md"};function l(d,t,h,c,p,u){return s(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="requesting-support-c-s-·-a-s" tabindex="-1">Requesting support (C/S · A/S) <a class="header-anchor" href="#requesting-support-c-s-·-a-s" aria-label="Permalink to &quot;Requesting support (C/S · A/S)&quot;">​</a></h1><p>How to file a request with Rainbow Robotics&#39; official support desks. The page runs in order: <strong>check it yourself → what to prepare → how to produce logs → where to send it.</strong> The submission links are at the <strong><a href="#where-to-send">bottom</a></strong> — a request that arrives complete is resolved far faster than one that starts a round of questions.</p><div class="danger custom-block"><p class="custom-block-title">⚠ If safety is involved, stop first</p><p>Fire, smoke, abnormal motion or risk of injury — carry out <a href="/RBQ/nightly/guides/common/emo.html">Emergency stop and recovery</a> before reading any further.</p></div><h2 id="before-you-ask" tabindex="-1">1. Check it yourself first <a class="header-anchor" href="#before-you-ask" aria-label="Permalink to &quot;1. Check it yourself first {#before-you-ask}&quot;">​</a></h2><p>Many symptoms already have an answer. Five minutes covers it.</p><ul><li><a href="/RBQ/nightly/manual/troubleshooting/joystick-not-working.html">Troubleshooting by symptom</a> — joystick not responding, no camera view, docking retries, and so on</li><li><a href="/RBQ/nightly/manual/gui/dashboard.html">Dashboard</a> — battery voltage and the <code>IMU</code>, <code>CAN</code>, <code>FindPose</code>, <code>Control</code> health</li><li><a href="/RBQ/nightly/manual/gui/logs.html">Logs and Black Box</a> — what error appeared at that moment</li></ul><p>None of that effort is wasted: <strong>write what you checked into the &quot;already tried&quot; section of the request below.</strong></p><h3 id="ask-ai" tabindex="-1">Ask the AI first <a class="header-anchor" href="#ask-ai" aria-label="Permalink to &quot;Ask the AI first {#ask-ai}&quot;">​</a></h3><p>This documentation site has a button that opens <strong>an AI grounded in the complete manual</strong>. Press <strong><code>Ask AI</code></strong> at the left of the top bar — it is on every page.</p><table tabindex="0"><thead><tr><th>What it does</th><th>Prepares a question that points the assistant at the full manual (<code>llms-full.txt</code>) and opens it in <strong>Claude</strong> or <strong>ChatGPT</strong></th></tr></thead><tbody><tr><td>Your options</td><td><code>Open in Claude</code> · <code>Open in ChatGPT</code> · <code>Copy prompt for AI</code> (to paste into another assistant)</td></tr><tr><td>Cost</td><td>You need an account with that AI service</td></tr></tbody></table><p><strong>It suits questions like</strong> — &quot;what is the center of mass measured from?&quot;, &quot;what is the difference between STAIRS mode and the Stairs motion?&quot;, &quot;what does this setting change?&quot; — anything <strong>the manual already answers</strong>. It is especially quick when the answer is spread across several pages.</p><div class="warning custom-block"><p class="custom-block-title">⚠ Do not take AI answers at face value</p><p>An AI can state <strong>a wrong answer convincingly</strong>. Always confirm the following against the manual itself or with support:</p><ul><li><strong>Safety and maintenance procedures</strong> — emergency stop, battery handling, disassembly</li><li><strong>Anything that actually moves the robot</strong> — read the source page before entering values</li><li><strong>Fault diagnosis</strong> — the AI cannot see your robot. File real faults through the steps below</li><li><strong>Recent changes</strong> — it does not know what has not reached the documentation yet</li></ul></div><h2 id="how-to-fill" tabindex="-1">2. What goes into the request <a class="header-anchor" href="#how-to-fill" aria-label="Permalink to &quot;2. What goes into the request {#how-to-fill}&quot;">​</a></h2><p>The CS and A/S forms use the same fields.</p><h3 id="product-info" tabindex="-1">Product details <a class="header-anchor" href="#product-info" aria-label="Permalink to &quot;Product details {#product-info}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>What to enter</th><th>Where to find it</th></tr></thead><tbody><tr><td><strong>Product type</strong></td><td><code>RBQ Series</code></td><td>—</td></tr><tr><td><strong>Product name</strong></td><td><code>RBQ10</code></td><td>—</td></tr><tr><td><strong>Serial number</strong></td><td>The robot&#39;s unique number</td><td>Under the robot&#39;s name in the hub&#39;s robot list and in the <code>Settings</code> title, or the label on the robot</td></tr><tr><td><strong>Installation date</strong></td><td><code>YYYY.MM.DD</code></td><td>Delivery / installation record</td></tr><tr><td><strong>Region</strong></td><td>Where the robot is</td><td>—</td></tr><tr><td><strong>Seller</strong></td><td>The dealer or contact you bought from</td><td>Purchase record</td></tr><tr><td><strong>Software in use</strong></td><td><code>Yes</code> / <code>No</code></td><td><code>Yes</code> if you drive the robot from the SDK or your own program</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">📝 Finding the serial number in the app</p><p><strong>Dashboard</strong> → the <code>Robot S/N</code> row at the top of the <strong>System</strong> card. The robot reports it, so it is read-only, and it only appears while connected. It is also under the robot&#39;s name in the hub&#39;s robot list and in the <code>Settings</code> title.</p></div><h3 id="payload" tabindex="-1">The payload you have fitted <a class="header-anchor" href="#payload" aria-label="Permalink to &quot;The payload you have fitted {#payload}&quot;">​</a></h3><p><strong>Always state what is mounted on the robot.</strong> Unstable walking and repeated falls most often come from payload mass and center-of-mass values that do not match reality. Without this, it is the first thing support has to ask for.</p><p>Three things to write down:</p><table tabindex="0"><thead><tr><th>Item</th><th>Example</th></tr></thead><tbody><tr><td><strong>What is fitted</strong></td><td>PTZ camera, Livox LiDAR ×2, LTE/5G module</td></tr><tr><td><strong>Values entered in the app</strong></td><td>Mounted slots <code>5 / 13</code> · total mass <code>7.19 kg</code> · CoM <code>(-0.006, 0, 0.173) m</code></td></tr><tr><td><strong>Do they match the hardware</strong></td><td>Whether you measured them, or left the defaults</td></tr></tbody></table><h4 id="where-to-read-payload" tabindex="-1">Where to read the values <a class="header-anchor" href="#where-to-read-payload" aria-label="Permalink to &quot;Where to read the values {#where-to-read-payload}&quot;">​</a></h4><p><strong>Settings › Payload setup</strong> shows which of the 13 slots are ticked and what each one holds. The <strong>total</strong> under the list is the overall mass and center of mass.</p><figure><img src="'+e+`" alt="Settings › Payload setup — slots and total"><figcaption style="text-align:center;">[ Capture the ticked slots with their values, plus the total below ]</figcaption></figure><p>The <strong>Dashboard › Config</strong> card summarizes the same values — <code>Mounted slots</code>, <code>Total mass</code> and <code>CoM X · Y · Z</code>. Either way, <strong>a screenshot carries all of it</strong> with no transcription.</p><div class="warning custom-block"><p class="custom-block-title">⚠ Check nothing is still ticked after removing a load</p><p>Removing equipment means unticking its slot as well. A slot left ticked makes the robot account for mass that is not there, and walking becomes unstable — a genuinely common cause. Entering values is covered in <a href="/RBQ/nightly/manual/gui/settings.html#robot-parameters">Settings › Payload setup</a>.</p></div><p>If you have just fitted or changed a payload, <strong>say whether you ran the ZMP calibration</strong> (<a href="/RBQ/nightly/guides/add-on/zmp-calibration.html">ZMP Calibration</a>). If not, doing that first may be the quicker route.</p><h3 id="inquiry-content" tabindex="-1">Writing the description <a class="header-anchor" href="#inquiry-content" aria-label="Permalink to &quot;Writing the description {#inquiry-content}&quot;">​</a></h3><p><strong>&quot;It doesn&#39;t work&quot; guarantees one extra round of email.</strong> Filling in the blocks below usually gets the cause narrowed down in the first reply. Copy the template as-is.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Symptom]</span></span>
<span class="line"><span>One line on what happens. (e.g. Switching to WALK, the robot collapses after 3 seconds)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[How to reproduce]</span></span>
<span class="line"><span>1. Robot on level ground, auto start completed</span></span>
<span class="line"><span>2. STAND → WALK</span></span>
<span class="line"><span>3. Push the left joystick forward; it collapses ~3 s later</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[When and how often]</span></span>
<span class="line"><span>Since around 2026-09-01 14:30. 8 times out of 10.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Software versions]</span></span>
<span class="line"><span>App: 1.2609.0   Robot: 1.2609.0   (Maintenance › Software update)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Payload fitted]</span></span>
<span class="line"><span>PTZ camera + Livox LiDAR ×2 + LTE/5G · slots 5/13 · 7.19 kg total</span></span>
<span class="line"><span>CoM (-0.006, 0, 0.173) m · measured values entered · ZMP calibration done</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Already tried]</span></span>
<span class="line"><span>- Rebooted the robot → unchanged</span></span>
<span class="line"><span>- Re-entered payload values → unchanged</span></span>
<span class="line"><span>- Ran the manual&#39;s &quot;If the robot falls&quot; procedure → recovers, but recurs</span></span></code></pre></div><p>The <strong>two version numbers (app and robot)</strong> are the ones most often left out, and a mismatch between them genuinely causes symptoms — it is the first thing support checks. Copy the <code>Version</code> values of <code>This app (GUI)</code> and <code>Current robot</code> straight from <strong>Maintenance › Software update</strong>.</p><h3 id="attachments" tabindex="-1">Attachments <a class="header-anchor" href="#attachments" aria-label="Permalink to &quot;Attachments {#attachments}&quot;">​</a></h3><p>The form takes <strong>one</strong> file, and only certain formats.</p><table tabindex="0"><thead><tr><th>Accepted</th><th><code>.jpg</code> · <code>.jpeg</code> · <code>.png</code> · <code>.pdf</code> · <code>.zip</code></th></tr></thead></table><div class="warning custom-block"><p class="custom-block-title">⚠ Log files cannot be uploaded as-is</p><p><code>.log</code>, <code>.txt</code> and <code>.csv</code> are rejected. <strong>Wrap them in a <code>.zip</code>.</strong> Put everything in one zip when you have more than one file to send.</p></div><p>What is worth attaching, in order of usefulness:</p><ol><li><strong>The Black Box zip</strong> — attitude and numeric recording from around the incident. The single most useful attachment.</li><li><strong>A screenshot of the payload configuration</strong> — see <a href="#where-to-read-payload">Where to read the values</a>.</li><li><strong>A screenshot showing the symptom</strong> — the error message, or abnormal values on the Dashboard.</li><li><strong>Video</strong> — if it is large, host it and put the link in the description instead.</li></ol><h3 id="contact" tabindex="-1">Contact details and consent <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact details and consent {#contact}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Note</th></tr></thead><tbody><tr><td>Company · department · name</td><td>—</td></tr><tr><td>Phone</td><td>—</td></tr><tr><td>Email</td><td><strong>This is where the reply goes.</strong> A typo means no answer</td></tr><tr><td>How you found us</td><td>Search · News · Exhibition · SNS · Referral · Other</td></tr><tr><td>Privacy consent</td><td><strong>Required — the form will not submit without it</strong></td></tr></tbody></table><h2 id="collect-logs" tabindex="-1">3. Producing the logs to attach <a class="header-anchor" href="#collect-logs" aria-label="Permalink to &quot;3. Producing the logs to attach {#collect-logs}&quot;">​</a></h2><p>Logs come from the <strong>Logs</strong> screen of the <strong>RBQ app</strong>. It has no menu entry — open it by tapping a red <strong>ERROR</strong> / <strong>FATAL</strong> toast, or a row in the alert badge popover in the control home&#39;s top bar. The screen itself is documented in <a href="/RBQ/nightly/manual/gui/logs.html">Logs and Black Box</a>.</p><h3 id="blackbox-zip" tabindex="-1">Black Box zip — do this first <a class="header-anchor" href="#blackbox-zip" aria-label="Permalink to &quot;Black Box zip — do this first {#blackbox-zip}&quot;">​</a></h3><p>For anything momentary — a fall, a fault — this one file is the most useful thing you can send. It carries the attitude, voltage and joint values from that instant alongside the log.</p><ol><li>Open <strong>Log → Black Box</strong>.</li><li>Choose the date and time window under <strong>DATE</strong> and <strong>SESSION</strong>.</li><li>Press <strong>Fetch</strong> to load the recording.</li><li>Scrub the transport bar to confirm <strong>it is the right window</strong>.</li><li>Press <strong>Save zip</strong> — attach that file as it is.</li></ol><figure><img src="`+o+`" alt="Black Box replay screen"><figcaption style="text-align:center;">[ Black Box — choose DATE and SESSION, then Save zip ]</figcaption></figure><h3 id="system-log" tabindex="-1">System log <a class="header-anchor" href="#system-log" aria-label="Permalink to &quot;System log {#system-log}&quot;">​</a></h3><p>Use this to send past logs by date.</p><ol><li>In <strong>Log → System Log</strong>, pick a day under <strong>DATE</strong> and press <strong>Fetch</strong>.</li><li>Leaving only <strong><code>WARNING</code>, <code>ERROR</code> and <code>FATAL</code></strong> in the level filter cuts the noise sharply.</li><li>Press <strong>Save</strong> to download the file.</li><li><strong>Zip the downloaded file</strong> before attaching it.</li></ol><h3 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot {#screenshot}&quot;">​</a></h3><p>If you can make the symptom happen again, this is the quickest route.</p><ol><li>Open <strong>Log → Real Time</strong>.</li><li><strong>Reproduce</strong> the symptom once.</li><li><strong>Screenshot</strong> the messages that appeared at that moment. Narrowing the level and process filters first makes it much easier to read.</li></ol><div class="tip custom-block"><p class="custom-block-title">📝 When it will not reproduce</p><p>Pick the day in <strong>System Log</strong> and capture around the time it happened. If you do not know the exact time, the rough window is enough.</p></div><h3 id="zip-together" tabindex="-1">Bundling several files <a class="header-anchor" href="#zip-together" aria-label="Permalink to &quot;Bundling several files {#zip-together}&quot;">​</a></h3><p>Only one attachment is accepted, so combine them.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux · macOS — after gathering the files in one folder</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">zip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq-support-2026-09-01.zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> folder-to-send/</span></span></code></pre></div><p>On Windows, right-click the folder and choose <strong>Compress to ZIP file</strong>. Putting the <strong>date and serial number</strong> in the filename makes it easier for support to find later.</p><h2 id="where-to-send" tabindex="-1">4. Filing it <a class="header-anchor" href="#where-to-send" aria-label="Permalink to &quot;4. Filing it {#where-to-send}&quot;">​</a></h2><p>With everything prepared, choose the desk below. There are two, and <strong>picking the wrong one delays the reply</strong> while it is handed to the right team.</p><table tabindex="0"><thead><tr><th>Situation</th><th>Desk</th></tr></thead><tbody><tr><td>A question about usage, features, settings or specifications</td><td><strong><a href="https://rainbow-robotics.com/en/customer-support/technical-support/cs-support/" target="_blank" rel="noreferrer">File a CS support request</a></strong></td></tr><tr><td>A fault or error that needs <strong>inspection or repair</strong></td><td><strong><a href="https://rainbow-robotics.com/en/customer-support/technical-support/as-support/" target="_blank" rel="noreferrer">File an A/S support request</a></strong></td></tr></tbody></table><p>The dividing line is simple — <strong>if the robot has to be shipped or someone has to visit, it is A/S</strong>; if an answer settles it, it is CS. When in doubt, file with CS; it gets routed internally.</p><p>There are developer-facing channels as well.</p><table tabindex="0"><thead><tr><th>Channel</th><th>For</th></tr></thead><tbody><tr><td><a href="https://github.com/RainbowRobotics/RBQ/issues" target="_blank" rel="noreferrer">GitHub Issues</a></td><td>Reproducible software bugs</td></tr><tr><td><a href="https://github.com/RainbowRobotics/RBQ/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a></td><td>Questions and feature requests</td></tr><tr><td><a href="mailto:rbq.support@rainbow-robotics.com" target="_blank" rel="noreferrer">rbq.support@rainbow-robotics.com</a></td><td>Private, business or licensing matters</td></tr></tbody></table><h2 id="after" tabindex="-1">5. After filing <a class="header-anchor" href="#after" aria-label="Permalink to &quot;5. After filing {#after}&quot;">​</a></h2><ul><li>The reply goes to <strong>the email address you entered</strong>. Check the spam folder too.</li><li>Reply <strong>in the same email thread</strong> when following up. Filing again splits the history.</li><li>If more logs are requested, repeat <a href="#collect-logs">Producing the logs to attach</a> and send them.</li><li>If the robot has to be shipped, follow the <a href="/RBQ/nightly/guides/common/packing.html">Packing</a> procedure.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also {#see-also}&quot;">​</a></h2><ul><li><a href="https://rainbow-robotics.com/en/customer-support/contact-us/" target="_blank" rel="noreferrer">Contact us</a> — sales and support contacts</li><li><a href="https://rainbow-robotics.com/en/customer-support/resources/" target="_blank" rel="noreferrer">Resources</a> — catalogues and documents</li><li><a href="/RBQ/nightly/manual/downloads/">Downloads</a> — app, robot software, CAD, manual PDFs</li></ul>`,66)])])}const y=a(i,[["render",l]]);export{b as __pageData,y as default};
